//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_qualifiedAttitude(value: *mut FlightStack::QualifiedAttitude) -> bool;
  fn get_referenceAndFdState(value: *mut FlightStack::ReferenceAndFdState) -> bool;
  fn put_apGuidance(value: *mut FlightStack::ApGuidanceAndValidity) -> bool;
}

pub fn unsafe_get_qualifiedAttitude() -> FlightStack::QualifiedAttitude
{
  unsafe {
    let value: *mut FlightStack::QualifiedAttitude = &mut FlightStack::QualifiedAttitude::default();
    get_qualifiedAttitude(value);
    return *value;
  }
}

pub fn unsafe_get_referenceAndFdState() -> FlightStack::ReferenceAndFdState
{
  unsafe {
    let value: *mut FlightStack::ReferenceAndFdState = &mut FlightStack::ReferenceAndFdState::default();
    get_referenceAndFdState(value);
    return *value;
  }
}

pub fn unsafe_put_apGuidance(value: &FlightStack::ApGuidanceAndValidity) -> bool
{
  unsafe {
    return put_apGuidance(value as *const FlightStack::ApGuidanceAndValidity as *mut FlightStack::ApGuidanceAndValidity);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_qualifiedAttitude: Mutex<Option<FlightStack::QualifiedAttitude>> = Mutex::new(None);
  pub static ref IN_referenceAndFdState: Mutex<Option<FlightStack::ReferenceAndFdState>> = Mutex::new(None);
  pub static ref OUT_apGuidance: Mutex<Option<FlightStack::ApGuidanceAndValidity>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_referenceAndFdState.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_apGuidance.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_qualifiedAttitude(value: *mut FlightStack::QualifiedAttitude) -> bool
{
  unsafe {
    let guard = IN_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_referenceAndFdState(value: *mut FlightStack::ReferenceAndFdState) -> bool
{
  unsafe {
    let guard = IN_referenceAndFdState.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_apGuidance(value: *mut FlightStack::ApGuidanceAndValidity) -> bool
{
  unsafe {
    *OUT_apGuidance.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
